#include "runtime.h"
namespace ShenPulse { namespace Hiking {
static int Seconds(const Request& r,int fallback){return std::max(1,std::min(3600,r.duration?r.duration:fallback));}
Result Execute(const Request& r){Ped ped;if(!Ready(ped))return {3,"Chargez une partie jouable, hors menus et cinematique."};const auto& c=r.code;const auto now=GetTickCount64();
 if(c=="hike_restart"){Start(now);return {0,"Nouvelle randonnee."};}
 if(!active||!progress.running)return {3,"Lancez une nouvelle randonnee."};
 if(c=="hike_forward"){if(progress.passed>=route.size())return {3,"Le parcours est termine."};Teleport(route[progress.passed]);return {0,"Point suivant rejoint."};}
 if(c=="hike_back"){if(!progress.passed)return {3,"Vous etes deja au premier point."};progress.passed--;Teleport(progress.passed?route[progress.passed-1]:startPoint);if(checkpointBlip)UI::REMOVE_BLIP(&checkpointBlip);return {0,"Retour au point precedent."};}
 if(c=="hike_start"){progress.passed=0;Teleport(startPoint);if(checkpointBlip)UI::REMOVE_BLIP(&checkpointBlip);return {0,"Retour au depart."};}
 if(c=="hike_rabbits")return SpawnActors(r,"a_c_rabbit_01",true);
 if(c=="hike_companion")return SpawnActors(r,"a_m_y_hiker_01",true);
 if(c=="hike_attackers")return SpawnActors(r,"g_m_y_mexgoon_02",false);
 if(c=="hike_funny_npc")return SpawnActors(r,"u_m_y_pogo_01",false);
 if(c=="hike_alien")return SpawnActors(r,"s_m_m_movalien_01",false);
 if(c=="hike_animal")return SpawnActors(r,"a_c_mtlion",false);
 if(c=="hike_clear"){ClearActors();return {0,"Personnages d'interactions retires."};}
 if(c=="hike_speed"){sprintUntil=now+Seconds(r,15)*1000;return {0,"Sprint accelere pendant "+std::to_string(Seconds(r,15))+" secondes."};}
 if(c=="hike_heal")return MontChiliad::Execute("chaos_heal");
 if(c=="hike_jump"){auto result=MontChiliad::StartSuperJumpEffect(ped,Seconds(r,20)*1000);if(!result.status)result.message="Super sauts pendant "+std::to_string(Seconds(r,20))+" secondes.";return result;}
 if(c=="hike_ragdoll"){auto result=MontChiliad::ForcePlayerRagdoll(ped,Seconds(r,3)*1000);if(!result.status)result.message="Chute pendant "+std::to_string(Seconds(r,3))+" secondes.";return result;}
 if(c=="hike_weapons"){WEAPON::GIVE_WEAPON_TO_PED(ped,MontChiliad::HashName("weapon_pistol"),120,FALSE,TRUE);return {0,"Pistolet et munitions offerts."};}
 if(c=="hike_disarm")return MontChiliad::Execute("chaos_remove_weapons");
 if(c=="hike_shield"){auto result=MontChiliad::Execute("chaos_invincible");MontChiliad::g_invincibleUntil=now+Seconds(r,20)*1000;return {result.status,"Protection temporaire pendant "+std::to_string(Seconds(r,20))+" secondes."};}
 if(c=="hike_quake"){quakeUntil=now+Seconds(r,12)*1000;nextQuake=0;return {0,"Seisme pendant "+std::to_string(Seconds(r,12))+" secondes."};}
 if(c=="hike_blackhole"){auto result=MontChiliad::Execute("chaos_black_hole");MontChiliad::g_blackHoleUntil=now+Seconds(r,12)*1000;MontChiliad::g_blackHolePullStartsAt=now+std::min(800,Seconds(r,12)*1000/3);MontChiliad::g_nextBlackHolePullAt=MontChiliad::g_blackHolePullStartsAt;return result;}
 if(c=="hike_ignite"){int count=0;for(const auto& a:actors)if(ENTITY::DOES_ENTITY_EXIST(a.ped)&&!a.friendly&&!ENTITY::IS_ENTITY_DEAD(a.ped)){FIRE::START_ENTITY_FIRE(a.ped);count++;}if(!count)return {3,"Faites d'abord apparaitre un adversaire a incendier."};return {0,std::to_string(count)+" adversaire(s) en feu."};}
 return {3,"Interaction Hiking inconnue."};
}
void ClearActors(){for(auto& a:actors)if(a.ped&&ENTITY::DOES_ENTITY_EXIST(a.ped)){FIRE::STOP_ENTITY_FIRE(a.ped);ENTITY::DELETE_ENTITY(&a.ped);}actors.clear();}
Result SpawnActors(const Request& r,const char* name,bool friendly){if(r.quantity>20)return {3,"Choisissez entre 1 et 20 personnages par interaction."};const int count=std::max(1,r.quantity);if(actors.size()+count>80)return {3,"La limite de 80 personnages est atteinte. Nettoyez les interactions."};auto loaded=MontChiliad::LoadModel(MontChiliad::HashName(name),name);if(loaded.status)return loaded;const auto now=GetTickCount64();Ped player=PLAYER::PLAYER_PED_ID();Point origin=Position(player);int created=0;
 for(int i=0;i<count;i++){float angle=static_cast<float>(i)*6.2831853f/count;float x=origin.x+std::cos(angle)*6,y=origin.y+std::sin(angle)*6;float ground=origin.z;if(!GAMEPLAY::GET_GROUND_Z_FOR_3D_COORD(x,y,origin.z+10,&ground,FALSE))ground=origin.z;const bool animal=std::string(name).rfind("a_c_",0)==0;Ped npc=PED::CREATE_PED(animal?28:4,MontChiliad::HashName(name),x,y,ground+0.3f,0,FALSE,FALSE);if(!npc||!ENTITY::DOES_ENTITY_EXIST(npc))continue;ENTITY::SET_ENTITY_AS_MISSION_ENTITY(npc,TRUE,TRUE);PED::SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(npc,friendly?TRUE:FALSE);PED::SET_PED_KEEP_TASK(npc,TRUE);if(friendly){PED::SET_PED_RELATIONSHIP_GROUP_HASH(npc,PED::GET_PED_RELATIONSHIP_GROUP_HASH(player));AI::TASK_FOLLOW_TO_OFFSET_OF_ENTITY(npc,player,2,1,0,3,-1,1.5f,TRUE);}else{PED::SET_PED_AS_ENEMY(npc,TRUE);static Hash hostileGroup=0;if(!hostileGroup)PED::ADD_RELATIONSHIP_GROUP(const_cast<char*>("SHENPULSE_HIKING_HOSTILE"),&hostileGroup);PED::SET_PED_RELATIONSHIP_GROUP_HASH(npc,hostileGroup);PED::SET_RELATIONSHIP_BETWEEN_GROUPS(5,hostileGroup,PED::GET_PED_RELATIONSHIP_GROUP_HASH(player));PED::SET_PED_COMBAT_ATTRIBUTES(npc,17,FALSE);PED::SET_PED_COMBAT_ATTRIBUTES(npc,63,FALSE);PED::SET_PED_COMBAT_ATTRIBUTES(npc,58,TRUE);PED::SET_PED_COMBAT_ATTRIBUTES(npc,5,TRUE);PED::SET_PED_COMBAT_ATTRIBUTES(npc,46,TRUE);PED::SET_PED_COMBAT_ABILITY(npc,2);PED::SET_PED_COMBAT_MOVEMENT(npc,3);PED::SET_PED_SEEING_RANGE(npc,150);PED::SET_PED_HEARING_RANGE(npc,150);PED::SET_PED_FLEE_ATTRIBUTES(npc,0,FALSE);if(r.code=="hike_attackers")WEAPON::GIVE_WEAPON_TO_PED(npc,MontChiliad::HashName("weapon_pistol"),120,FALSE,TRUE);AI::TASK_COMBAT_PED(npc,player,0,16);}actors.push_back({npc,r.viewer,now+180000,friendly,now+2000});created++;}
 STREAMING::SET_MODEL_AS_NO_LONGER_NEEDED(MontChiliad::HashName(name));return created?Result{0,std::to_string(created)+" personnage(s) cree(s)."}:Result{3,"GTA n'a cree aucun personnage."};}
void TickActors(ULONGLONG now){for(auto it=actors.begin();it!=actors.end();){if(!ENTITY::DOES_ENTITY_EXIST(it->ped)||now>=it->until||ENTITY::IS_ENTITY_DEAD(it->ped)){if(ENTITY::DOES_ENTITY_EXIST(it->ped))ENTITY::DELETE_ENTITY(&it->ped);it=actors.erase(it);continue;}if(!it->friendly&&now>=it->nextTask&&!PED::IS_PED_IN_COMBAT(it->ped,PLAYER::PLAYER_PED_ID())){it->nextTask=now+2000;AI::CLEAR_PED_TASKS(it->ped);const auto distance=Distance(Position(it->ped),Position(PLAYER::PLAYER_PED_ID()));if(PED::GET_PED_TYPE(it->ped)==28){if(distance>2.5f)AI::TASK_GO_TO_ENTITY(it->ped,PLAYER::PLAYER_PED_ID(),-1,1.5f,4.0f,0,0);else AI::TASK_PUT_PED_DIRECTLY_INTO_MELEE(it->ped,PLAYER::PLAYER_PED_ID(),0,-1,0,FALSE);}else AI::TASK_COMBAT_PED(it->ped,PLAYER::PLAYER_PED_ID(),0,16);}if(!it->name.empty()){Point p=Position(it->ped);float x,y;if(invoke<BOOL>(0x34E82F05DF2974F5,p.x,p.y,p.z+1.15f,&x,&y))DrawText(it->name,x,y,.25f,it->friendly?50:255,it->friendly?255:100,180);}++it;}}
} }
